from pathlib import Path
import json,hashlib,subprocess
from datetime import datetime,timezone
from scripts.vertex_concept_review import _call_model,MODEL
r=Path('catalog/source-facts-escalation-v1');prompt='Search only official pokemon-card.com sources: what are the four S8b Morpeko V-UNION numbers on publisher page40208, and the release date of M6a 30th Celebration? Does page50574 (Mew, MF premium deck) supply evidence for M6a G/R? Give concise primary URLs and explicit remaining gaps. Research date 2026-10-03. No card identity or price approvals.'
p=dict(schema='pokemon.missing-source-grounded-research.v1',model=MODEL,prompt=prompt,prompt_sha256=hashlib.sha256(prompt.encode()).hexdigest(),requested_at=datetime.now(timezone.utc).isoformat(),catalog_context_visible=True,prior_research_leads_visible=True,google_search_grounding_enabled=True,scope='Source discovery only; no pixel readings or catalog import. Previous response hit MAX_TOKENS and was not accepted.')
(r/'grounded-research-protocol-v3.json').write_text(json.dumps(p,indent=2)+'\n');token=subprocess.check_output(['gcloud','auth','print-access-token'],text=True,stderr=subprocess.DEVNULL).strip();response=_call_model('pivota-staging','global',token,dict(contents=[dict(role='user',parts=[dict(text=prompt)])],tools=[dict(googleSearch={})],generationConfig=dict(maxOutputTokens=8192)))
assert response['modelVersion']==MODEL;(r/'grounded-research-response-v3.json').write_text(json.dumps(dict(response=response,completed_at=datetime.now(timezone.utc).isoformat(),protocol_sha256=hashlib.sha256((r/'grounded-research-protocol-v3.json').read_bytes()).hexdigest()),ensure_ascii=False,indent=2)+'\n');print(json.dumps(dict(finish=[c.get('finishReason') for c in response['candidates']],grounding_metadata_present=any('groundingMetadata' in c for c in response['candidates']))))
